lemma antisymm_of_WCWF {R : α → α → Prop} : WCWF R → AntiSymmetric R := by
  contrapose;
  simp [AntiSymmetric];
  intro x y Rxy Ryz hxy;
  apply ConverseWellFounded.iff_has_max.not.mpr;
  push_neg;
  use {x, y};
  constructor;
  . simp;
  . intro z hz;
    by_cases z = x;
    . use y; simp_all [Relation.IrreflGen];
    . use x; simp_all [Relation.IrreflGen];

